import Foundation
import MeshSitesCore

/// Runs the shared protocol vectors (protocol/vectors/*.json, generated by the
/// TypeScript reference) against MeshSitesCore. Used by the `meshsites-vectors`
/// executable and by the XCTest target.
public struct VectorCheck {
    public let name: String
    public let passed: Bool
    public let detail: String
}

public enum VectorRunner {
    /// protocol/vectors relative to this source file.
    public static var defaultVectorsDir: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("protocol/vectors")
    }

    public static func runAll(vectorsDir: URL = defaultVectorsDir) -> [VectorCheck] {
        var out: [VectorCheck] = []
        func check(_ name: String, _ ok: Bool, _ detail: @autoclosure () -> String = "") {
            out.append(VectorCheck(name: name, passed: ok, detail: ok ? "" : detail()))
        }
        func bytes(_ path: String) -> Bytes? {
            (try? Data(contentsOf: vectorsDir.appendingPathComponent(path))).map { Array($0) }
        }
        func json(_ path: String) -> JSON? {
            guard let b = bytes(path) else {
                check("load \(path)", false, "file not found")
                return nil
            }
            do { return try JSON.parse(b) } catch {
                check("parse \(path)", false, "\(error)")
                return nil
            }
        }

        // Keccak known answers.
        check("keccak256(\"\")", Hex.encode(Keccak.hash256([])) == "c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470")
        check("keccak256(\"abc\")", Hex.encode(Keccak.hash256(Array("abc".utf8))) == "4e03657aea45a94fc7d47ba826c8d667c0d1e6e33a64a036ec44f58fa12d6c45")
        let long = Bytes(repeating: 0x61, count: 200) // spans two 136-byte blocks
        check("keccak256 multi-block", Hex.encode(Keccak.hash256(long)) == Hex.encode(Keccak.hash256(Array(long))))

        // ---- car.json
        if let car = json("car.json"), let carFile = car["car"]?.string, let siteCar = bytes(carFile), let rootCid = car["rootCid"]?.string {
            let v = Verify.verifyCar(siteCar, expectedRoot: rootCid)
            check("site-basic.car verifies", v.ok, v.errors.joined(separator: "; "))
            check("site-basic root", v.root?.description == rootCid, "got \(v.root?.description ?? "nil")")
            check("site-basic totalBytes", v.totalBytes == Int(car["totalBytes"]?.int ?? -1), "got \(v.totalBytes)")
            if let read = try? Verify.readCar(siteCar), let expected = car["blocks"]?.array {
                let got = read.order.map { "\($0):\(read.blocks[$0]!.count)" }
                let want = expected.map { "\($0["cid"]?.string ?? ""):\($0["size"]?.int ?? -1)" }
                check("site-basic block order and sizes", got == want, "got \(got)")
                let src = DictBlockSource(read.blocks)
                for (path, file) in [("", "index.html"), ("js/app.js", "js/app.js"), ("css/site.css", "css/site.css")] {
                    let want = bytes("site-basic/\(file)")
                    if case .file(_, let b, _)? = try? Resolver.resolve(root: read.root, path: path, source: src) {
                        check("resolve /\(path)", b == want, "bytes differ (\(b.count) vs \(want?.count ?? -1))")
                    } else {
                        check("resolve /\(path)", false, "not a file")
                    }
                }
                check("resolve css → redirect", (try? Resolver.resolve(root: read.root, path: "css", source: src)) == .redirect(location: "css/"))
                check("resolve missing → not found", (try? Resolver.resolve(root: read.root, path: "nope.html", source: src)) == .notFound)
                check("resolve .. → not found", (try? Resolver.resolve(root: read.root, path: "css/../index.html", source: src)) == .notFound)
            } else {
                check("site-basic readCar", false, "readCar failed")
            }
            if let hint = car["origCidHint"]?.string {
                check("CIDv0 round-trip", (try? CID.parse(hint))?.description == hint)
            }
            check("CIDv1 round-trip", (try? CID.parse(rootCid))?.description == rootCid)
            for n in car["negatives"]?.array ?? [] {
                guard let file = n["file"]?.string, let want = n["expect"]?["errorContains"]?.string, let b = bytes(file) else {
                    check("negative vector", false, "malformed vector")
                    continue
                }
                let r = Verify.verifyCar(b)
                check("negative \(file)", !r.ok && r.errors.contains { $0.contains(want) }, "expected an error containing \"\(want)\", got \(r.errors)")
            }
        }

        // ---- records.json
        if let rec = json("records.json") {
            for k in rec["testKeys"]?.array ?? [] {
                let priv = Hex.decode(String((k["privateKey"]?.string ?? "").dropFirst(2))) ?? []
                check("test key \(k["seed"]?.string ?? "")", Records.address(fromPrivateKey: priv) == k["address"]?.string)
            }
            for s in rec["signing"]?.array ?? [] {
                guard let r = s["record"], let name = r["name"]?.string else { continue }
                let msg = try? Records.message(r)
                check("signing \(name): canonical JSON", msg.map { String(decoding: $0, as: UTF8.self) } == s["canonicalJson"]?.string,
                      "got \(msg.map { String(decoding: $0, as: UTF8.self) } ?? "error")")
                check("signing \(name): UTF-8 hex", msg.map(Hex.encode) == s["canonicalJsonUtf8Hex"]?.string)
                check("signing \(name): EIP-191 hash", msg.map { "0x" + Hex.encode(Records.eip191Hash($0)) } == s["eip191Hash"]?.string)
                let rec = msg.flatMap { try? Records.recoverSigner(message: $0, signature: s["sig"]?.string ?? "") }
                check("signing \(name): recover", rec == r["signer"]?.string, "got \(rec ?? "error")")
            }
            for c in rec["cases"]?.array ?? [] {
                guard let id = c["id"]?.string, let input = c["input"], let expect = c["expect"] else { continue }
                let o = c["options"]
                let res = Records.verify(input, expectedSigner: o?["expectedSigner"]?.string, cachedSeq: o?["cachedSeq"]?.int, now: o?["now"]?.int ?? Int64(Date().timeIntervalSince1970))
                switch (res, expect["ok"]) {
                case (.ok(let status, _, let signer), .bool(true)?):
                    check("record \(id)", status.rawValue == expect["status"]?.string && signer == expect["signer"]?.string, "got \(status) \(signer)")
                case (.rejected(let reason, let detail), .bool(false)?):
                    check("record \(id)", reason.rawValue == expect["reason"]?.string, "got \(reason.rawValue): \(detail)")
                default:
                    check("record \(id)", false, "got \(res)")
                }
            }
        }

        // ---- canonical-json.json
        if let cj = json("canonical-json.json") {
            for c in cj["cases"]?.array ?? [] {
                guard let input = c["input"], let want = c["output"]?.string else { continue }
                let got = try? input.canonical()
                check("canonical \(want)", got == want, "got \(got ?? "error")")
                check("canonical hex \(want)", got.map { Hex.encode(Array($0.utf8)) } == c["outputUtf8Hex"]?.string)
            }
            for c in cj["mustReject"]?.array ?? [] {
                guard let text = c["input"]?.string else { continue }
                let rejected: Bool
                if let v = try? JSON.parse(text) { rejected = (try? v.canonical()) == nil } else { rejected = true }
                check("canonical rejects \(c["why"]?.string ?? text)", rejected)
            }
        }

        // ---- wire.json
        if let w = json("wire.json") {
            for v in w["valid"]?.array ?? [] {
                guard let id = v["id"]?.string, let hex = v["hex"]?.string, let b = Hex.decode(hex) else { continue }
                do {
                    guard let m = try Wire.decode(b) else { check("wire \(id)", false, "decoded as unknown"); continue }
                    let re = try Wire.encode(m)
                    check("wire \(id) round-trip", Hex.encode(re) == hex, "re-encoded \(Hex.encode(re))")
                } catch {
                    check("wire \(id)", false, "\(error)")
                }
            }
            for v in w["invalid"]?.array ?? [] {
                guard let id = v["id"]?.string, let hex = v["hex"]?.string, let b = Hex.decode(hex), let want = v["expect"]?.string else { continue }
                let got: String
                do { got = try Wire.decode(b) == nil ? "ignore" : "valid" } catch { got = "invalid" }
                check("wire \(id): \(want)", got == want, "got \(got)")
            }
        }

        // ---- gossip.json (M3 gossip policy)
        if let g = json("gossip.json"), let selfID = g["self"]?.string {
            for sc in g["scenarios"]?.array ?? [] {
                guard let id = sc["id"]?.string, let nowSec = sc["nowSec"]?.int, let cfgJ = sc["config"] else { check("gossip scenario", false, "malformed"); continue }
                var cfg = Gossip.Config()
                cfg.seeding = cfgJ["seeding"] == .bool(true)
                cfg.bulkCapable = cfgJ["bulkCapable"] == .bool(true)
                func num(_ j: JSON?) -> Double? {
                    switch j { case .int(let i)?: return Double(i); case .double(let d)?: return d; default: return nil }
                }
                cfg.announceIntervalMs = num(cfgJ["announceIntervalMs"]) ?? cfg.announceIntervalMs
                cfg.nameRebroadcastMs = num(cfgJ["nameRebroadcastMs"]) ?? cfg.nameRebroadcastMs
                cfg.seenReqMs = num(cfgJ["seenReqMs"]) ?? cfg.seenReqMs
                cfg.heardMs = num(cfgJ["heardMs"]) ?? cfg.heardMs
                if let b = cfgJ["want"], let burst = num(b["burst"]), let r = num(b["refillMs"]) { cfg.want = .init(burst: burst, refillMs: r) }
                if let b = cfgJ["nameRecord"], let burst = num(b["burst"]), let r = num(b["refillMs"]) { cfg.nameRecord = .init(burst: burst, refillMs: r) }

                let node = Gossip(selfID: selfID, config: cfg)
                let setup = sc["setup"]
                for s in setup?["sites"]?.array ?? [] {
                    guard let r = s["root"]?.string, let root = try? CID.parse(r), let size = s["sizeBytes"]?.int, let count = s["blockCount"]?.int else { continue }
                    node.setSite(.init(root: root, sizeBytes: UInt32(size), blockCount: UInt16(count), complete: true))
                }
                for (n, a) in setup?["signers"]?.object ?? [:] { if let a = a.string { node.trust(name: n, signer: a) } }
                for r in setup?["records"]?.array ?? [] {
                    if let t = r.string { do { try node.addRecord(t, nowSec: nowSec) } catch { check("gossip \(id) setup record", false, "\(error)") } }
                }

                var failures: [String] = []
                for (i, st) in (sc["steps"]?.array ?? []).enumerated() {
                    guard let sender = st["sender"]?.string, let ttl = st["ttl"]?.int, let hex = st["payloadHex"]?.string, let payload = Hex.decode(hex),
                          let at = num(st["at"]), let e = st["expect"] else { failures.append("step \(i): malformed"); continue }
                    let v = node.receive(.init(sender: sender, recipient: st["recipient"]?.string, ttl: UInt8(ttl), payload: payload,
                                               authenticated: st["authenticated"] == .bool(true)), now: at, nowSec: nowSec)
                    var why: [String] = []
                    if v.relay != (e["relay"] == .bool(true)) { why.append("relay \(v.relay)") }
                    if v.drop != e["drop"]?.string { why.append("drop \(v.drop ?? "nil") (want \(e["drop"]?.string ?? "nil"))") }
                    if v.spam != (e["spam"] == .bool(true)) { why.append("spam \(v.spam)") }
                    let wantHave = e["have"]
                    if (v.have == nil) != (wantHave == nil) || (v.have.map { $0.from != wantHave?["from"]?.string || Hex.encode($0.reqId) != wantHave?["reqIdHex"]?.string } ?? false) {
                        why.append("have \(String(describing: v.have))")
                    }
                    let wantName = e["name"]
                    if v.name?.name != wantName?["name"]?.string || v.name?.status.rawValue != wantName?["status"]?.string || v.name?.root != wantName?["root"]?.string {
                        why.append("name \(String(describing: v.name))")
                    }
                    let wantSend = e["send"]?.array ?? []
                    let gotSend = v.send.map { o -> String in
                        "\((try? Wire.encode(o.message)).map(Hex.encode) ?? "encode-error")/\(o.ttl)/\(o.recipient ?? "")"
                    }
                    let expSend = wantSend.map { "\($0["payloadHex"]?.string ?? "")/\($0["ttl"]?.int ?? -1)/\($0["recipient"]?.string ?? "")" }
                    if gotSend != expSend { why.append("send \(gotSend) (want \(expSend))") }
                    if !why.isEmpty { failures.append("step \(i): " + why.joined(separator: ", ")) }
                }
                check("gossip \(id)", failures.isEmpty, failures.joined(separator: "; "))
            }
        }

        // ---- the real meshsites.eth record (release/), as set on-chain
        let release = vectorsDir.deletingLastPathComponent().deletingLastPathComponent().appendingPathComponent("release")
        if let b = try? Data(contentsOf: release.appendingPathComponent("meshsites.record.signed.json")), let signed = try? JSON.parse(Array(b)) {
            let ts = signed["record"]?["ts"]?.int ?? 0
            let res = Records.verify(signed, expectedSigner: "0x8E0783451d07Ba750f201Ae9bF6d93385E6dA410", now: ts)
            if case .ok(.verified, let r, _) = res {
                check("meshsites.eth record verifies", r.name == "meshsites.eth")
                if let car = try? Data(contentsOf: release.appendingPathComponent("meshsites.car")) {
                    let v = Verify.verifyCar(Array(car), expectedRoot: r.cid.description)
                    check("meshsites.eth mesh CAR matches record.cid", v.ok, v.errors.joined(separator: "; "))
                }
            } else {
                check("meshsites.eth record verifies", false, "\(res)")
            }
        }
        return out
    }
}
